(function() {
  'use strict';

  // 教学用简化数据：二元对称马尔可夫信源
  // 状态：0 或 1
  // 转移概率：P(下一位=当前位) = a, P(下一位!=当前位) = 1-a
  // 稳态分布：P(0) = 0.5, P(1) = 0.5 (因为对称)
  // 边际熵 H(X) = 1 bit (恒定)
  // 熵率 H = h2(a) = -a*log2(a) - (1-a)*log2(1-a)

  function binaryEntropy(p) {
    if (p === 0 || p === 1) return 0;
    return -p * Math.log2(p) - (1 - p) * Math.log2(1 - p);
  }

  function generateText(a, length = 200) {
    let text = '';
    let current = Math.random() < 0.5 ? '0' : '1';
    text += current;

    for (let i = 1; i < length; i++) {
      const r = Math.random();
      if (r < a) {
        // 保持当前符号
        // current remains same
      } else {
        // 翻转符号
        current = current === '0' ? '1' : '0';
      }
      text += current;
    }
    return text;
  }

  // 初始化
  const slider = document.getElementById('prob-slider');
  const sliderValDisplay = document.getElementById('slider-val-display');
  const generateBtn = document.getElementById('generate-btn');
  const resetBtn = document.getElementById('reset-btn');
  const textOutput = document.getElementById('text-output');
  const marginalEntropyEl = document.getElementById('marginal-entropy');
  const entropyRateEl = document.getElementById('entropy-rate');
  const redundancyEl = document.getElementById('redundancy-value');

  const MAX_ENTROPY = 1.0; // 二元信源最大熵

  function updateDisplay() {
    const a = parseFloat(slider.value);
    sliderValDisplay.textContent = a.toFixed(2);

    const text = generateText(a);
    textOutput.textContent = text;

    // 计算指标
    const hMarginal = 1.0; // 恒定，因为稳态分布是 0.5/0.5
    const hRate = binaryEntropy(a);
    const redundancy = ((MAX_ENTROPY - hRate) / MAX_ENTROPY * 100);

    // 更新 DOM 和数据属性
    marginalEntropyEl.textContent = hMarginal.toFixed(2) + ' bits';
    marginalEntropyEl.setAttribute('data-value', hMarginal.toFixed(2));

    entropyRateEl.textContent = hRate.toFixed(2) + ' bits';
    entropyRateEl.setAttribute('data-value', hRate.toFixed(2));

    redundancyEl.textContent = redundancy.toFixed(1) + '%';
    redundancyEl.setAttribute('data-value', redundancy.toFixed(1));
  }

  generateBtn.addEventListener('click', updateDisplay);
  resetBtn.addEventListener('click', () => {
    slider.value = 0.80;
    updateDisplay();
  });
  slider.addEventListener('input', updateDisplay);

  // 初始运行
  updateDisplay();
})();
